// Shared game constants. app/Game/Pieces.php and app/Game/Rules.php mirror these
// exactly; tests/Fixtures/engine-parity.json (generated by PHP) keeps them honest.

export const WIDTH = 10;
export const HEIGHT = 22; // rows 0-1 are the hidden spawn area
export const HIDDEN_ROWS = 2;
export const EMPTY = '.';
export const GARBAGE = 'G';

export const PIECE_TYPES = ['I', 'J', 'L', 'O', 'S', 'T', 'Z'];

// Rotation-state-0 cells as [x, y] inside the piece's bounding box (y grows downward).
const BASE_SHAPES = {
    I: { size: 4, cells: [[0, 1], [1, 1], [2, 1], [3, 1]] },
    J: { size: 3, cells: [[0, 0], [0, 1], [1, 1], [2, 1]] },
    L: { size: 3, cells: [[2, 0], [0, 1], [1, 1], [2, 1]] },
    O: { size: 4, cells: [[1, 0], [2, 0], [1, 1], [2, 1]] },
    S: { size: 3, cells: [[1, 0], [2, 0], [0, 1], [1, 1]] },
    T: { size: 3, cells: [[1, 0], [0, 1], [1, 1], [2, 1]] },
    Z: { size: 3, cells: [[0, 0], [1, 0], [1, 1], [2, 1]] },
};

/** SHAPES[type][rotation] = [[x, y], ...]; rotation is clockwise 0..3. */
export const SHAPES = Object.fromEntries(
    Object.entries(BASE_SHAPES).map(([type, { size, cells }]) => {
        const rotations = [cells];
        for (let r = 1; r < 4; r++) {
            const prev = rotations[r - 1];
            rotations.push(type === 'O' ? prev : prev.map(([x, y]) => [size - 1 - y, x]));
        }
        return [type, rotations];
    }),
);

export const SPAWN_X = 3;
export const SPAWN_Y = 0;

// SRS wall kicks, converted to y-down. Key is "from>to".
const KICKS_JLSTZ = {
    '0>1': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
    '1>0': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
    '1>2': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
    '2>1': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
    '2>3': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
    '3>2': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
    '3>0': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
    '0>3': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
};
const KICKS_I = {
    '0>1': [[0, 0], [-2, 0], [1, 0], [-2, 1], [1, -2]],
    '1>0': [[0, 0], [2, 0], [-1, 0], [2, -1], [-1, 2]],
    '1>2': [[0, 0], [-1, 0], [2, 0], [-1, -2], [2, 1]],
    '2>1': [[0, 0], [1, 0], [-2, 0], [1, 2], [-2, -1]],
    '2>3': [[0, 0], [2, 0], [-1, 0], [2, -1], [-1, 2]],
    '3>2': [[0, 0], [-2, 0], [1, 0], [-2, 1], [1, -2]],
    '3>0': [[0, 0], [1, 0], [-2, 0], [1, 2], [-2, -1]],
    '0>3': [[0, 0], [-1, 0], [2, 0], [-1, -2], [2, 1]],
};

export function kicksFor(type, from, to) {
    if (type === 'O') return [[0, 0]];
    return (type === 'I' ? KICKS_I : KICKS_JLSTZ)[`${from}>${to}`];
}

